INSERT INTO representatives (entity, body, title, name, bio, webpage_url, photo_url, emails, phones, social_accounts, elections, "start", "end", district, district_description, district_bounds)
SELECT seed.entity, seed.body, seed.title, seed.name, seed.bio, seed.webpage_url, seed.photo_url,
  seed.emails, seed.phones, seed.social_accounts, seed.elections,
  COALESCE(seed."start", (
    SELECT min((election ->> 'date')::date)::timestamp
    FROM jsonb_array_elements(seed.elections) AS election
    WHERE (election ->> 'date')::date < CURRENT_DATE
  )),
  seed."end", seed.district, seed.district_description, seed.district_bounds
FROM seed
WHERE NOT EXISTS (
  SELECT 1 FROM representatives existing
  WHERE existing.entity = seed.entity
    AND existing.body = seed.body
    AND existing.district = seed.district
    AND existing.name = seed.name
);

COMMIT;
